input.command:
cd /tmp/tarvo_scripts && cat > detail.py <<'EOF'
import sys, re, openpyxl
D=sys.argv[1]
wb = openpyxl.load_workbook("/tmp/tarvo_scripts/PonteCambio_Relatorio_TARVO_092026.xlsx", data_only=True)
ws = wb["Operações"]; hdr=[c.value for c in ws[5]]
ops=[dict(zip(hdr,[c.value for c in r])) for r in ws.iter_rows(min_row=6) if r[0].value and str(r[0].value).startswith("PC-")]
for o in ops:
    if o["Nº Operação"]=="PC-0926-0162" or not o["Status Compliance"] or o["Observação"] or (o["Spread R$"] or 0)<0 or not o["CNPJ Cliente"] or "67869675" in str(o["CNPJ Cliente"]):
        print({k:(v.strftime('%d/%m') if hasattr(v,'strftime') else v) for k,v in o.items() if k not in ("Valor ME","Taxa Cliente","PTAX Ref.","IOF R$")})
print("ops PC:",len(ops))
L=open(f"{D}/05a_extrato_banco_aurora_cc4471_set2026.csv",encoding="utf-8").read().splitlines()
for i,l in enumerate(L,1):
    if re.search(r"PIX RECEBIDO|DEVOLUCAO|DARF|ISS|TRANSF|GPS|GRF|AMAZON|GOOGLE|CONTAB",l): print(f"L{i}",l)
ofx=open(f"{D}/05b_extrato_banco_meridiano_cc90233_set2026.ofx",encoding="cp1252").read()
for t in re.findall(r"<STMTTRN>(.*?)</STMTTRN>",ofx,re.S):
    m=re.search(r"<MEMO>(.*)",t).group(1).strip()
    if not m.startswith("PIX RECEB"):
        print(re.search(r"<FITID>(.*)",t).group(1).strip(), re.search(r"<DTPOSTED>(\d{8})",t).group(1), re.search(r"<TRNAMT>(.*)",t).group(1).strip(), m)
EOF
uv run --quiet --with openpyxl python -I detail.py /home/<usuario>/Projetos/Sandbox/Tarvo_Data_Pack_set2026

